// Приём у Ворна: каждый шаг — действия, видимые только на своём этапе (движок/приём.js).
const действияПриёма = () => [
  { вид: 'действие', текст: 'Ответить на вопросы Ворна', подпись: S => `лечение ${цены(S).скидка} гр. вместо ${цены(S).полная}`,
    условие: S => этапПриёма(S) === 'режим', эффект: { приёмРежим: 'ответы' } },
  { вид: 'действие', текст: 'Заплатить полностью и промолчать', подпись: S => `лечение ${цены(S).полная} гр.`,
    условие: S => этапПриёма(S) === 'режим', эффект: { приёмРежим: 'молчать' } },
  ...Object.entries(ВОПРОСЫ_ЛЕКАРЯ).flatMap(([id, в]) => в.ответы.map((о, i) => ({ вид: 'действие', текст: о.текст, подпись: '',
    условие: S => вопросСейчас(S)?.id === id, эффект: { приёмОтвет: i } }))),
  { вид: 'действие', текст: 'Лечиться', стоит: S => ценаЛечения(S), подпись: 'цел +1…+2 · 1 ход',
    условие: S => этапПриёма(S) === 'исход' && естьЧтоЛечить(S), эффект: { лечить: 'полное', ход: 1 } },
  { вид: 'действие', текст: 'Взять настойку Ворна', стоит: НАСТОЙКА.цена, подпись: 'слабее · цел +1 · 1 ход',
    условие: S => этапПриёма(S) === 'исход' && естьЧтоЛечить(S), эффект: { лечить: 'настойка', ход: 1 } },
  { вид: 'действие', текст: 'Закончить приём без лечения', подпись: '1 ход',
    условие: S => этапПриёма(S) === 'исход', эффект: { лечить: 'нет', ход: 1 } },
];

