const платаТрудом = Object.entries(ТРУД).map(([ключ, т]) => действие(т.текст, undefined, 1,
  { условие: S => этапТорга(S) === 'плата' && S.герой.тело[т.тело] >= 1, подпись: 'вес 1 · ' + т.подпись, эффект: торг({ вид: 'плата', как: 'труд', ключ }) }));
const платаЧужой = [0, 1, 2].map(i => действие(S => { const т = чужиеПравды(S)[i]; return `Отдать чужую правду: «${т?.ярлык ?? ''}»`; }, undefined, 1,
  { условие: S => этапТорга(S) === 'плата' && !!чужиеПравды(S)[i], подпись: S => `вес ${чужиеПравды(S)[i]?.ценность ?? 1} · 1 ход`, эффект: торг({ вид: 'плата', как: 'тема', слот: i }) }));
const платаСвоей = [0, 1, 2].map(i => действие(S => `Сказать о себе: «${своиПравды(S)[i]?.текст ?? ''}»`, undefined, 1,
  { условие: S => этапТорга(S) === 'плата' && !!своиПравды(S)[i], подпись: 'вес 2 · 1 ход', эффект: торг({ вид: 'плата', как: 'факт', слот: i }) }));

